export function shellView(content,current,{brand,icon,themeButton,esc,name,banner,storageOK}){
 const nav=[['dashboard','grid','Dashboard'],['tryout','file','Tryout UKPPPG'],['latihan','book','Latihan per topik'],['pedagogi','bulb','Pedagogi Umum'],['riwayat','chart','Hasil & pembahasan'],['referensi','layers','Referensi & UKin']];
 const page=nav.find(n=>n[0]===current)?.[2]||'Hasil latihan';
 const initials=esc(name.slice(0,2).toUpperCase());
 return `<aside class="sidebar" aria-label="Navigasi utama"><div class="sidebar-brand">${brand()}<button type="button" class="sidebar-close" data-action="menu" aria-label="Tutup navigasi">${icon('close')}</button></div><p class="brand-caption">Ruang tumbuh calon guru.</p><div class="nav-label">RUANG BELAJAR</div><nav>${nav.map(([r,i,t])=>`<a class="nav-item ${current===r?'active':''}" href="#${r}" ${current===r?'aria-current="page"':''}>${icon(i)}${t}${r==='tryout'?'<span class="count">80</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="journey-note"><h4>Sedikit setiap hari.</h4><p>Setiap soal yang dipahami adalah satu langkah menuju kelas impianmu.</p></div><button type="button" class="profile" data-action="profile" aria-label="Ubah nama profil"><span class="avatar">${initials}</span><span><span class="profile-name">${esc(name)}</span><span class="small" style="display:block">Calon Guru · Informatika</span></span>${icon('settings')}</button></div></aside><button type="button" class="nav-backdrop" data-action="menu" aria-label="Tutup navigasi"></button>
 <div class="workspace"><header class="topbar"><div class="desktop-breadcrumb breadcrumb">Ruang belajar <span>/</span><strong>${page}</strong></div><div class="mobile-brand">${brand()}</div><div class="top-meta"><span class="top-pace">Belajar sesuai ritmemu</span><span class="year">Acuan 2026</span>${themeButton()}<button type="button" class="mobile-profile avatar" data-action="profile" aria-label="Ubah nama profil">${initials}</button></div></header><main id="main" class="main" tabindex="-1">${!storageOK?'<div class="notification">Penyimpanan browser tidak tersedia. Sesi ini hanya tersimpan selama halaman tetap terbuka.</div>':''}${banner()}${content}<footer class="footer"><span>© 2026 Nalar. Dibuat untuk perjalanan belajarmu.</span><span>Latihan mandiri · Soal orisinal · Tidak berafiliasi dengan penyelenggara UKPPPG</span></footer></main></div>
 <nav class="bottom-nav" aria-label="Navigasi ponsel">${[['dashboard','grid','Beranda'],['tryout','file','Tryout'],['latihan','book','Latihan'],['pedagogi','bulb','Pedagogi']].map(([r,i,t])=>`<a href="#${r}" class="${current===r?'active':''}" ${current===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}<button type="button" class="more-toggle ${['riwayat','referensi'].includes(current)?'active':''}" data-action="menu" aria-label="Buka navigasi lainnya" aria-expanded="false">${icon('menu')}<span>Lainnya</span></button></nav>`;
}
